/bin/bash -lc "cat > /tmp/check-liquid-cat.cjs <<'EOF'
const fs=require('fs');
(async()=>{
const tabs=await(await fetch('http://127.0.0.1:9222/json')).json();
const ws=new WebSocket(tabs[0].webSocketDebuggerUrl);await new Promise(r=>ws.addEventListener('open',r));
let id=0;const pending=new Map(),errors=[];
ws.addEventListener('message',e=>{const m=JSON.parse(e.data);if(m.id){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(m.error):p.resolve(m.result)}else if(m.method==='Runtime.exceptionThrown')errors.push(m.params.exceptionDetails)});
const send=(method,params={})=>new Promise((resolve,reject)=>{const n=++id;pending.set(n,{resolve,reject});ws.send(JSON.stringify({id:n,method,params}))});
const js=async expression=>(await send('Runtime.evaluate',{expression,returnByValue:true})).result.value;
await send('Runtime.enable');await send('Page.enable');
await send('Emulation.setDeviceMetricsOverride',{width:1200,height:920,deviceScaleFactor:1,mobile:false});
await send('Page.navigate',{url:'file:///tmp/work/liquid-cat.html'});
await new Promise(r=>setTimeout(r,600));
await js(\"document.getElementById('play').click()\");
for(const t of [0,2.3,3.6,5,6.6,8.9,10.3]){
 await js("'`document.getElementById('"'scrub').value="'${t};document.getElementById('"'scrub').dispatchEvent(new Event('input'))"'`);
 await new Promise(r=>setTimeout(r,60));
 const shot=await send('"'Page.captureScreenshot',{format:'png'});fs.writeFileSync("'`/tmp/cat-${t}.png`,Buffer.from(shot.data,'"'base64'));
}
console.log('Paused:',await js(\"document.getElementById('playText').textContent\"));
await js(\"document.getElementById('speed').click()\");console.log('Speed:',await js(\"document.getElementById('speed').textContent\"));
await js(\"document.getElementById('replay').click()\");console.log('Replay:',await js(\"({state:document.getElementById('playText').textContent,time:document.getElementById('scrub').value})\"));
await send('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});
const mobile=await send('Page.captureScreenshot',{format:'png'});fs.writeFileSync('/tmp/cat-mobile.png',Buffer.from(mobile.data,'base64'));
console.log('Mobile overflow:',await js('document.documentElement.scrollWidth>innerWidth'));
await send('Emulation.setEmulatedMedia',{features:[{name:'prefers-reduced-motion',value:'reduce'}]});await send('Page.reload');await new Promise(r=>setTimeout(r,500));
console.log('Reduced motion:',await js(\"document.getElementById('playText').textContent\"));
console.log('Errors:',errors);ws.close();
})().catch(e=>{console.error(e);process.exit(1)});
EOF
node /tmp/check-liquid-cat.cjs"

